<script lang="ts">
 import {onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {readCatalogue,checkPublicRepository,publicationBody,repositoryName,type PublicTab} from '../island/catalogue';
 import {TAB_PROMPT,EXAMPLE_TAB,validateTab,TAB_ICONS,MAX_TAB_BYTES,type TabPackage,type TabIcon} from '../island/extensions';
 import {connectionStatus,saveConnection,removeConnection,cleanupExtension} from '../island/extensionRuntime';
 import ExtensionIcon from './ExtensionIcon.svelte';
 let {tabs,onchange,repository,onrepository,disabledTabs=[],ondisabled}:{tabs:TabPackage[];onchange:(tabs:TabPackage[])=>void;repository:string;onrepository:(repo:string)=>void;disabledTabs?:string[];ondisabled?:(ids:string[])=>void}=$props();
 let panel=$state<'installed'|'create'|'community'>('installed'), status=$state(''),query=$state('');
 let entries=$state.raw<PublicTab[]>([]),busy=$state(false),pending=$state<TabPackage|null>(null);
 let secrets=$state<Record<string,string>>({}),saved=$state<Record<string,boolean>>({});
 let controller:AbortController|undefined;
 onDestroy(()=>controller?.abort());
 const filtered=$derived(tabs.filter(t=>t.name.toLowerCase().includes(query.toLowerCase())));
 let lastRepository='';
 $effect(()=>{const next=repository;if(next===lastRepository)return;lastRepository=next;controller?.abort();entries=[];});
 function error(e:unknown){return e instanceof Error?e.message:String(e);}
 async function refresh(){if(busy)return;busy=true;controller=new AbortController();try{entries=await readCatalogue(repository,controller.signal);status=`Found ${entries.length} public extensions.`;}catch(e){status=error(e);}finally{busy=false;}}
 async function publish(tab:TabPackage){
  if(busy)return;busy=true;controller=new AbortController();
  try{const body=publicationBody(tab);if(body.length>60000)throw Error('This package is too large for the GitHub issue catalogue. Reduce its code below 60,000 characters before publishing.');await checkPublicRepository(repository,controller.signal);await navigator.clipboard.writeText(body);if(!await invoke<boolean>('open_catalogue_draft',{repository,title:tab.name}))throw Error('Could not open GitHub.');status='Package copied. Paste it into the GitHub draft and submit to publish. Connection credentials and saved extension data are never included.';}
  catch(e){status=error(e);}finally{busy=false;}
 }
 function review(tab:TabPackage){pending=validateTab(tab);status='';}
 function install(){if(!pending)return;try{const tab=validateTab(pending);if(tabs.length>=12&&!tabs.some(t=>t.id===tab.id))throw Error('Remove an extension before adding another (12 maximum).');onchange([...tabs.filter(t=>t.id!==tab.id),tab]);ondisabled?.(disabledTabs.filter(id=>id!==tab.id));pending=null;panel='installed';status=`Installed ${tab.name}. Its icon is on the left side of Home.`;}catch(e){status=error(e);}}
 async function load(file?:File){if(!file)return;try{if(file.size>MAX_TAB_BYTES)throw Error('Choose a JSON package up to 120 KB.');const value=JSON.parse(await file.text());if(value&&typeof value==='object'&&!value.icon)value.icon='sparkles';review(validateTab(value));}catch(e){status=error(e);}}
 function exportTab(tab:TabPackage){const u=URL.createObjectURL(new Blob([JSON.stringify(tab,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=tab.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 function edit(tab:TabPackage,patch:Partial<TabPackage>){try{const edited=validateTab({...tab,...patch});onchange(tabs.map(t=>t.id===tab.id?edited:t));status='Extension details saved.';}catch(e){status=error(e);}}
 async function remove(tab:TabPackage){try{await cleanupExtension(tab);onchange(tabs.filter(t=>t.id!==tab.id));ondisabled?.(disabledTabs.filter(id=>id!==tab.id));status=`Removed ${tab.name}, its saved data and connections.`;}catch(e){status=error(e);}}
 async function checkConnections(tab:TabPackage){if(tab.version!==2)return;for(const c of tab.connections){try{saved[tab.id+':'+c.id]=await connectionStatus(tab,c.id);}catch{saved[tab.id+':'+c.id]=false;}}}
 async function credential(tab:TabPackage,id:string,clear=false){busy=true;try{const key=tab.id+':'+id;if(clear)await removeConnection(tab,id);else await saveConnection(tab,id,secrets[key]||'');secrets[key]='';saved[key]=!clear;status=clear?'Connection credential removed.':'Credential saved in Windows Credential Manager. The service will check whether it is valid when used.';}catch(e){status=error(e);}finally{busy=false;}}
</script>
<div class="market">
 <div class="intro"><h3>Your extensions</h3><p>Add useful tools to Home. Everything stays private on this PC until you choose to publish it.</p></div>
 <nav aria-label="Marketplace views">{#each [{id:'installed',label:'Installed'},{id:'create',label:'Create & import'},{id:'community',label:'Community'}] as item}<button type="button" aria-pressed={panel===item.id} onclick={()=>{panel=item.id as typeof panel;status='';}}>{item.label}{item.id==='installed'?' · '+tabs.length:''}</button>{/each}</nav>
 {#if pending}
  <section class="review" aria-label="Review extension"><h4>Review before adding</h4><label>Name<input aria-label="Extension name" maxlength="40" value={pending.name} oninput={e=>{if(pending)pending={...pending,name:e.currentTarget.value};}}/></label>
   <fieldset><legend>Choose its Home icon</legend><div class="icon-picker">{#each TAB_ICONS as icon}<button type="button" aria-label={'Use '+icon+' icon'} aria-pressed={(pending.icon??'sparkles')===icon} onclick={()=>{if(pending)pending={...pending,icon};}}><ExtensionIcon name={icon}/></button>{/each}</div></fieldset>
   <p>{pending.version===2?'Runs its own interface and JavaScript inside an isolated tab.':'A classic tab with built-in display blocks.'}</p>
   {#if pending.version===2}<h5>Requested connections</h5>{#if pending.permissions.network.length}<ul>{#each pending.permissions.network as origin}<li>{origin}</li>{/each}</ul><p>Installing allows this code to make requests to these services. Review code you import. Account credentials are added separately below after installation.</p>{:else}<p>Local only. No network access requested.</p>{/if}{/if}
   <div class="actions"><button type="button" class="pill-btn primary" onclick={install}>{tabs.some(t=>t.id===pending?.id)?'Approve & replace':'Approve & install'}</button><button type="button" class="pill-btn" onclick={()=>pending=null}>Cancel</button></div>
  </section>
 {:else if panel==='installed'}
  <div class="toolbar"><input aria-label="Find installed extensions" placeholder="Find an extension…" bind:value={query}/><label class="file-button pill-btn">Import<input aria-label="Import an extension" type="file" accept=".json,application/json" onchange={e=>{void load(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label></div>
  {#each filtered as tab (tab.id)}<article class="installed"><header><span class="package-icon"><ExtensionIcon name={tab.icon}/></span><span><strong>{tab.name}</strong><small>{tab.version===2?'Interactive extension':'Classic tab'} · {entries.some(e=>JSON.stringify(e.tab)===JSON.stringify(tab))?'Published copy':'Local copy'}</small></span><label class="enable"><input type="checkbox" role="switch" aria-label={'Enable '+tab.name} checked={!disabledTabs.includes(tab.id)} onchange={e=>ondisabled?.(e.currentTarget.checked?disabledTabs.filter(id=>id!==tab.id):[...disabledTabs,tab.id])}/></label></header>
   <details ontoggle={e=>{if(e.currentTarget.open)void checkConnections(tab);}}><summary>Manage extension</summary><label>Display name<input aria-label={'Name for '+tab.name} maxlength="40" value={tab.name} onchange={e=>edit(tab,{name:e.currentTarget.value})}/></label><label>Home icon<select aria-label={'Icon for '+tab.name} value={tab.icon??'sparkles'} onchange={e=>edit(tab,{icon:e.currentTarget.value as TabIcon})}>{#each TAB_ICONS as icon}<option value={icon}>{icon}</option>{/each}</select></label>
   {#if tab.version===2}{#if tab.permissions.network.length}<p>Network access: {tab.permissions.network.join(', ')}</p>{:else}<p>Runs locally without network access.</p>{/if}
    {#each tab.connections as c}<div class="connection"><label>{c.name}<small>{c.origin} · {saved[tab.id+':'+c.id]?'Credential saved':'Not configured'}</small><input type="password" aria-label={c.name+' for '+tab.name} autocomplete="new-password" placeholder="Enter account credential" bind:value={secrets[tab.id+':'+c.id]}/></label><div class="actions"><button type="button" class="pill-btn" disabled={busy||!secrets[tab.id+':'+c.id]} onclick={()=>void credential(tab,c.id)}>Save credential</button><button type="button" class="pill-btn" disabled={busy||!saved[tab.id+':'+c.id]} onclick={()=>void credential(tab,c.id,true)}>Disconnect</button></div></div>{/each}
   {/if}
   <div class="actions"><button type="button" class="pill-btn" onclick={()=>exportTab(tab)}>Export file</button><button type="button" class="pill-btn" disabled={busy} onclick={()=>void publish(tab)}>Publish on GitHub</button><button type="button" class="pill-btn danger" disabled={busy} onclick={()=>void remove(tab)}>Remove</button></div><small>Removing also deletes this extension’s saved data and credentials.</small></details>
  </article>{:else}<div class="empty"><ExtensionIcon name="code"/><h4>{query?'No matching extensions':'Your space, your tools'}</h4><p>Use Create & import to give an AI the compatible format, then bring its JSON file here.</p><button type="button" class="pill-btn" onclick={()=>panel='create'}>Create an extension</button></div>{/each}
 {:else if panel==='create'}
  <section class="step"><span class="step-number">1</span><div><h4>Describe your tool to your AI</h4><p>Copy the environment guide below with your request. It defines the real SDK, interface size, icon choices, connections and validation rules.</p><button type="button" class="pill-btn" onclick={()=>navigator.clipboard.writeText(TAB_PROMPT).then(()=>status='Authoring guide copied. Give it to your AI with the tool you want to build.').catch(()=>status='Select and copy the guide below.')}>Copy AI authoring guide</button><details><summary>Read the authoring guide</summary><textarea aria-label="AI authoring prompt" readonly value={TAB_PROMPT} rows="7"></textarea></details></div></section>
  <section class="step"><span class="step-number">2</span><div><h4>Import and review its file</h4><p>Choose the JSON, select an icon, review requested network access and install. No project setup or code compilation is needed.</p><label class="file-button pill-btn">Choose extension file<input aria-label="Import an extension package" type="file" accept=".json,application/json" onchange={e=>{void load(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label></div></section>
  <section class="step"><span class="step-number">3</span><div><h4>Connect services when needed</h4><p>A live inbox needs a real email account connection. Credentials are configured in Manage extension and stay outside exported files. The AI must implement loading, errors and disconnected states.</p></div></section>
  <button type="button" class="pill-btn" onclick={()=>review(EXAMPLE_TAB)}>Try the working counter example</button>
 {:else}
  <h4>Community catalogue</h4><p>Browse extensions shared through public GitHub issues. Downloading and installing makes a local copy; it does not connect your accounts.</p>
  <label>Catalogue repository<input aria-label="GitHub catalogue repository" value={repository} onchange={e=>{try{onrepository(repositoryName(e.currentTarget.value.trim()));}catch(error){status=error instanceof Error?error.message:'Invalid repository';}}}/></label>
  <button type="button" class="pill-btn" disabled={busy} onclick={()=>void refresh()}>{busy?'Loading…':'Load public catalogue'}</button>
  {#each entries as entry (entry.url)}<article class="installed"><header><span class="package-icon"><ExtensionIcon name={entry.tab.icon}/></span><span><strong>{entry.tab.name}</strong><small>By {entry.author}</small></span><button type="button" class="pill-btn" onclick={()=>review(entry.tab)}>Review</button></header></article>{/each}
  <details><summary>How publishing works</summary><p>Use Publish on GitHub under an installed extension. Sudo copies the package and opens an issue draft. Paste, review and submit on GitHub to make it public. Closing its issue withdraws the catalogue listing. Previously downloaded copies remain with their owners.</p></details>
 {/if}
 {#if status}<p class="status" role="status">{status}</p>{/if}
</div>
<style>
 .market{font:var(--type-body)}h3{font:600 17px/22px var(--font-sans);margin:4px 0}h4{font:600 13px/18px var(--font-sans);margin:0 0 5px}h5{font:600 12px/18px var(--font-sans);margin:8px 0}p{font:var(--type-caption);opacity:.75;line-height:18px;margin:6px 0 12px}.intro{margin:7px 0 14px}nav{display:flex;border-radius:11px;padding:3px;background:#ffffff08;gap:3px;margin-bottom:14px}nav button{flex:1;color:inherit;background:transparent;border:0;border-radius:8px;min-height:30px;font:500 11px/16px var(--font-sans);cursor:pointer}nav button[aria-pressed=true]{background:#ffffff17}label{display:block;font:500 12px/16px var(--font-sans);margin:10px 0}input,textarea,select{display:block;margin-top:6px;width:100%;box-sizing:border-box;font:var(--type-caption);color:inherit;background:#ffffff08;border:1px solid #ffffff22;border-radius:9px;padding:8px 10px;color-scheme:dark}select{width:auto;min-width:120px}option{background:#24262d;color:#f5f5f5}textarea{resize:vertical}small{display:block;font:var(--type-caption);opacity:.65;margin-top:4px}.toolbar{display:flex;align-items:center;gap:8px;margin:8px 0 14px}.toolbar input{margin:0;min-width:0}.file-button{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;margin:0;white-space:nowrap;flex:none}.file-button:focus-within{outline:2px solid var(--focus-ring);outline-offset:2px}.file-button input{position:absolute;inset:0;opacity:0;cursor:pointer;margin:0;padding:0}.installed{border:1px solid #ffffff16;border-radius:13px;padding:12px;margin:9px 0;background:#ffffff03}header{display:flex;align-items:center;gap:9px}header>span:nth-child(2){flex:1;min-width:0}strong{font:560 13px/18px var(--font-sans);overflow-wrap:anywhere}.package-icon{display:grid;place-items:center;width:32px;height:32px;flex:none;border:1px solid #ffffff19;background:#ffffff08;border-radius:10px}.enable{margin:0}.enable input{appearance:none;width:32px;height:19px;position:relative;padding:0;border:0;border-radius:20px;background:#72737c;cursor:pointer}.enable input::before{content:'';position:absolute;left:3px;top:3px;width:13px;height:13px;border-radius:50%;background:#f5f5f5}.enable input:checked{background:var(--accent)}.enable input:checked::before{transform:translateX(13px);background:var(--on-accent)}details{margin:12px 0 2px}summary{cursor:pointer;font:500 12px/18px var(--font-sans);opacity:.85}.actions{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.primary{background:var(--accent);color:var(--on-accent)}.danger{color:#ffcbcb}.empty{text-align:center;padding:25px 18px;color:var(--text-primary)}.empty>:global(svg){margin-bottom:10px}.review{border:1px solid #ffffff30;border-radius:14px;background:#ffffff05;padding:14px;margin-bottom:14px}.review ul{font:var(--type-caption);padding-left:17px;overflow-wrap:anywhere}fieldset{padding:0;border:0;margin:14px 0}legend{font:500 12px/18px var(--font-sans)}.icon-picker{display:grid;grid-template-columns:repeat(6,1fr);gap:5px;margin-top:7px}.icon-picker button{display:grid;place-items:center;min-height:34px;border:1px solid #ffffff19;border-radius:9px;background:#ffffff05;color:inherit;cursor:pointer}.icon-picker button[aria-pressed=true]{border-color:#ffffff80;background:#ffffff1b}.step{display:flex;gap:11px;margin:18px 0}.step-number{display:grid;place-items:center;border:1px solid #ffffff30;border-radius:50%;width:24px;height:24px;flex:none;font:500 11px var(--font-sans)}.step>div{min-width:0}.connection{border-left:2px solid #ffffff20;padding-left:10px;margin:13px 0}.status{padding:10px 12px;border:1px solid #ffffff24;border-radius:10px;opacity:1;overflow-wrap:anywhere}
</style>
